{
  "name": "De Prada & Moya Real Estate - Dossier Premium",
  "description": "Digital premium dossier for property owners, showcasing the agency's methodology, philosophy, and collaboration formats with a sober and elegant editorial style."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface DossierPageContent {
  id: number;
  title: string;
  subtitle?: string;
  content: React.ReactNode;
}

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Menu, X } from 'lucide-react';
import Cover from './pages/Cover';
import Introduction from './pages/Introduction';
import Philosophy from './pages/Philosophy';
import HowWeWork from './pages/HowWeWork';
import FormatBasic from './pages/FormatBasic';
import FormatPremium from './pages/FormatPremium';
import FormatLoyalty from './pages/FormatLoyalty';
import DecisionLogic from './pages/DecisionLogic';
import OurStory from './pages/OurStory';
import Closing from './pages/Closing';
import Contact from './pages/Contact';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState(0);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const pages = [
    { component: <Cover />, title: 'Portada' },
    { component: <Introduction />, title: 'Introducción' },
    { component: <Philosophy />, title: 'Filosofía' },
    { component: <HowWeWork />, title: 'Cómo trabajamos' },
    { component: <FormatBasic />, title: 'Formato Basic' },
    { component: <FormatPremium />, title: 'Formato Premium' },
    { component: <FormatLoyalty />, title: 'Formato Loyalty' },
    { component: <DecisionLogic />, title: 'Elección' },
    { component: <OurStory />, title: 'Nuestra Historia' },
    { component: <Closing />, title: 'Cierre' },
    { component: <Contact />, title: 'Contacto' },
  ];

  const nextPage = () => {
    if (currentPage < pages.length - 1) setCurrentPage(prev => prev + 1);
  };

  const prevPage = () => {
    if (currentPage > 0) setCurrentPage(prev => prev - 1);
  };

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [currentPage]);

  return (
    <div className="min-h-screen flex flex-col relative overflow-hidden selection:bg-stone-200">
      {/* Header / Nav Overlay */}
      <header className="fixed top-0 left-0 right-0 z-50 px-6 py-4 flex justify-between items-center mix-blend-difference text-white">
        <div className="text-sm tracking-widest uppercase font-medium">
          De Prada & Moya
        </div>
        <button 
          onClick={() => setIsMenuOpen(!isMenuOpen)}
          className="p-2 hover:opacity-70 transition-opacity"
        >
          {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {/* Fullscreen Menu */}
      {isMenuOpen && (
        <div className="fixed inset-0 z-40 bg-stone-900 text-stone-100 flex flex-col justify-center px-12 md:px-24">
          <nav className="space-y-4">
            {pages.map((page, idx) => (
              <button
                key={idx}
                onClick={() => {
                  setCurrentPage(idx);
                  setIsMenuOpen(false);
                }}
                className={`block text-2xl md:text-4xl serif hover:italic transition-all ${currentPage === idx ? 'opacity-100 italic' : 'opacity-40 hover:opacity-100'}`}
              >
                <span className="text-sm mr-4 opacity-50 font-sans not-italic">{String(idx + 1).padStart(2, '0')}</span>
                {page.title}
              </button>
            ))}
          </nav>
        </div>
      )}

      {/* Main Content Area */}
      <main className="flex-grow flex items-center justify-center p-4 md:p-12 mt-12 mb-12">
        <div className="w-full max-w-5xl mx-auto page-transition bg-white shadow-sm min-h-[85vh] flex flex-col">
          {pages[currentPage].component}
        </div>
      </main>

      {/* Footer Navigation */}
      <footer className="fixed bottom-0 left-0 right-0 px-6 py-6 flex justify-between items-center bg-white/80 backdrop-blur-sm border-t border-stone-100">
        <div className="text-xs uppercase tracking-tighter text-stone-400">
          Página {currentPage + 1} de {pages.length}
        </div>
        <div className="flex gap-8">
          <button 
            onClick={prevPage}
            disabled={currentPage === 0}
            className={`flex items-center gap-2 text-sm uppercase tracking-widest font-medium transition-opacity ${currentPage === 0 ? 'opacity-10' : 'opacity-100 hover:opacity-60'}`}
          >
            <ChevronLeft size={16} /> Anterior
          </button>
          <button 
            onClick={nextPage}
            disabled={currentPage === pages.length - 1}
            className={`flex items-center gap-2 text-sm uppercase tracking-widest font-medium transition-opacity ${currentPage === pages.length - 1 ? 'opacity-10' : 'opacity-100 hover:opacity-60'}`}
          >
            Siguiente <ChevronRight size={16} />
          </button>
        </div>
      </footer>
    </div>
  );
};

export default App;

