      <div className="fixed right-10 top-1/2 -translate-y-1/2 flex flex-col gap-4 z-[90] hidden md:flex">
         {pages.map((_, i) => (
           <div 
            key={i} 
            onClick={() => setCurrentPage(i)}
            className={`w-1.5 transition-all duration-500 cursor-pointer ${currentPage === i ? 'h-8 bg-bronze' : 'h-2 bg-stone-300 hover:bg-stone-400'}`} 
           />
         ))}
      </div>

      {/* Botón Siguiente Flotante (Abajo Derecha) */}
      {currentPage < pages.length - 1 && (
        <button 
          onClick={handleNext}
          className="fixed bottom-10 right-10 z-[100] bg-white text-forest p-5 shadow-2xl rounded-full border border-stone-100 hover:bg-bronze hover:text-white transition-all group"
        >
          <ArrowDown size={24} className="group-hover:translate-y-1 transition-transform" />
        </button>
      )}

      {/* Modal de Detalles */}
      <ModalDetalle isOpen={!!modalData} onClose={() => setModalData(null)} data={modalData} />

      <style>{`
        .animate-fade-in {
          animation: fadeIn 0.8s ease-out forwards;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

