const PlanWizard = ({ onSelect }: { onSelect: (id: string) => void }) => {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState<Record<string, string>>({});

  const questions = [
    {
      id: 'agencias',
      text: '¿Con cuántas agencias quieres trabajar?',
      options: [
        { label: 'Máximo 2 (Basic)', val: 'basico' },
        { label: 'Solo con vosotros (Premium/Loyalty)', val: 'exclusivo' }
      ]
    },
    {
      id: 'objetivo',
      text: '¿Cuál es tu prioridad?',
      options: [
        { label: 'Solo vender bien (Basic/Premium)', val: 'venta' },
        { label: 'Invertir para revalorizar (Loyalty)', val: 'inversion' },
        { label: 'Algo especial / Discreción (A Medida)', val: 'amedida' }
      ]
    }
  ];

  const handleSelect = (val: string) => {
    const newAnswers = { ...answers, [questions[step].id]: val };
    setAnswers(newAnswers);
    if (step < questions.length - 1) {
      setStep(step + 1);
    } else {
      if (newAnswers.objetivo === 'amedida') onSelect('amedida');
      else if (newAnswers.objetivo === 'inversion') onSelect('loyalty');
      else if (newAnswers.agencias === 'basico') onSelect('basico');
      else onSelect('premium');
    }
  };

  return (
    <div className="bg-white p-8 md:p-12 shadow-2xl border border-stone-100 relative overflow-hidden max-w-xl mx-auto">
      <div className="absolute top-0 left-0 w-full h-1 bg-stone-100">
        <div className="h-full bg-bronze transition-all duration-500" style={{ width: `${((step + 1) / questions.length) * 100}%` }}></div>
      </div>
      <div className="relative z-10">
        <span className="text-bronze text-[10px] uppercase tracking-widest font-bold mb-4 block">Asistente de Selección</span>
        <h3 className="serif text-2xl text-forest mb-8 italic">{questions[step].text}</h3>
        <div className="flex flex-col gap-4">
          {questions[step].options.map((opt, i) => (
            <button key={i} onClick={() => handleSelect(opt.val)} className="group flex items-center justify-between p-4 border border-stone-200 hover:border-bronze hover:bg-stone-50 transition-all text-left">
              <span className="text-sm font-medium text-forest">{opt.label}</span>
              <ChevronRight size={16} className="text-stone-300 group-hover:text-bronze group-hover:translate-x-1 transition-all" />
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

