                <p className="text-xs text-white/50 italic leading-relaxed">Deborah De Prada aporta la seguridad jurídica que las agencias tradicionales no pueden ofrecer.</p>
              </div>
              <div className="space-y-4">
                <History className="text-bronze" size={32} />
                <p className="text-xs font-bold uppercase tracking-widest">30 Años en Mallorca</p>
                <p className="text-xs text-white/50 italic leading-relaxed">Conocemos cada rincón de la isla, su mercado real y su red de contactos estratégica.</p>
              </div>
              <div className="space-y-4">
                <Sparkles className="text-bronze" size={32} />
                <p className="text-xs font-bold uppercase tracking-widest">Trato Boutique</p>
                <p className="text-xs text-white/50 italic leading-relaxed">No somos una gran oficina masiva. Somos su interlocutor directo para un servicio de autor.</p>
              </div>
            </div>
          </div>
        </section>

        {/* PÁGINA 8: RESEÑAS */}
        <section className={`absolute inset-0 flex items-center justify-center p-6 bg-white transition-all duration-700 ease-in-out ${currentPage === 7 ? 'opacity-100 z-10' : 'opacity-0 z-0 pointer-events-none'}`}>
          <div className="max-w-5xl w-full h-full flex flex-col items-center justify-center text-center">
            <div className="mb-10 flex gap-2 justify-center">{[1,2,3,4,5].map(i => <Star key={i} fill="#b38b59" color="#b38b59" size={32} />)}</div>
            <span className="text-bronze text-[10px] font-bold uppercase tracking-[0.4em] mb-4">Lo que dicen nuestros clientes</span>
            <h2 className="serif text-4xl md:text-7xl text-forest italic leading-tight mb-12 font-light tracking-tight">Eficacia probada en <br /> operaciones reales.</h2>
            <div className="flex gap-20 items-center mb-16">
               <div className="text-center">
                 <p className="text-7xl font-light text-forest serif">4.9</p>
                 <p className="text-[10px] uppercase tracking-widest font-bold text-stone-400 mt-2">Puntuación Google</p>
               </div>
               <div className="h-20 w-px bg-stone-100 hidden md:block"></div>
               <div className="text-center">
                 <p className="text-7xl font-light text-forest serif">240+</p>
                 <p className="text-[10px] uppercase tracking-widest font-bold text-stone-400 mt-2">Opiniones Verificadas</p>
               </div>
            </div>
            <a href={LINKS.resenas} target="_blank" className="bg-forest text-white px-12 py-6 text-[10px] uppercase tracking-[0.3em] font-bold hover:bg-bronze transition-all shadow-xl flex items-center gap-4 group">
              Leer Reseñas en Google <ExternalLink size={16} />
            </a>
          </div>
        </section>

        {/* PÁGINA 9: CONTACTO FINAL */}
        <section className={`absolute inset-0 flex items-center justify-center p-6 bg-sand transition-all duration-700 ease-in-out ${currentPage === 8 ? 'opacity-100 z-10' : 'opacity-0 z-0 pointer-events-none'}`}>
          <div className="max-w-5xl w-full h-full flex flex-col items-center justify-center text-center">
             <div className="w-24 h-24 bg-forest rounded-full flex items-center justify-center text-bronze shadow-2xl mb-12">
               <MessageCircle size={40} />
             </div>
             <h2 className="serif text-6xl md:text-9xl text-forest italic mb-8 font-light tracking-tight">Hablemos.</h2>
             <p className="text-stone-500 text-xl md:text-2xl font-light max-w-2xl mx-auto mb-16 italic">
               Estamos en Palma, Campos y Cala Pi. <br /> Listos para su cambio de vida.
             </p>
             <div className="grid md:grid-cols-3 gap-8 mb-20 w-full max-w-4xl">
                <div className="bg-white p-10 border border-stone-100 shadow-sm flex flex-col items-center group hover:border-bronze transition-colors">
                  <MapPin size={28} className="text-bronze mb-4" />
                  <h4 className="serif text-3xl text-forest font-light">Palma</h4>
                </div>
                <div className="bg-white p-10 border border-stone-100 shadow-sm flex flex-col items-center group hover:border-bronze transition-colors">
                  <MapPin size={28} className="text-bronze mb-4" />
                  <h4 className="serif text-3xl text-forest font-light">Campos</h4>
                </div>
                <div className="bg-white p-10 border border-stone-100 shadow-sm flex flex-col items-center group hover:border-bronze transition-colors">
                  <MapPin size={28} className="text-bronze mb-4" />
                  <h4 className="serif text-3xl text-forest font-light">Cala Pi</h4>
                </div>
             </div>
             <a href={generateWhatsAppURL()} target="_blank" className="bg-forest text-white px-16 py-8 text-xs uppercase tracking-[0.3em] font-bold hover:bg-bronze transition-all shadow-2xl flex items-center gap-6">
               WhatsApp de Atención Directa <MessageCircle size={22} />
             </a>
          </div>
        </section>
      </main>

      {/* NAVEGACIÓN UX FLOTANTE */}
      <div className="fixed bottom-10 right-10 z-[100] flex gap-4">
        {currentPage > 0 && (
          <button onClick={handlePrev} className="bg-white text-forest p-6 shadow-2xl rounded-full border border-stone-100 hover:bg-bronze hover:text-white transition-all transform hover:-translate-x-2">
            <ArrowLeft size={28} />
          </button>
        )}
        {currentPage < pages.length - 1 && (
          <button onClick={handleNext} className="bg-white text-forest p-6 shadow-2xl rounded-full border border-stone-100 hover:bg-bronze hover:text-white transition-all transform hover:translate-x-2">
            <ArrowRight size={28} />
          </button>
        )}
      </div>

      {/* FOOTER INDICATOR */}
      <div className="fixed bottom-10 left-10 z-[70] hidden md:flex items-center gap-4">
        <div className="h-[2px] w-24 bg-stone-200">
           <div className="h-full bg-bronze transition-all duration-700" style={{ width: `${((currentPage + 1) / pages.length) * 100}%` }}></div>
        </div>
        <span className="text-[10px] uppercase tracking-widest font-bold text-stone-400">Página {currentPage + 1} / {pages.length}</span>
      </div>

      <ModalDetalle isOpen={!!modalData} onClose={() => setModalData(null)} data={modalData} />

      <style>{`
        .animate-fade-in { animation: fadeIn 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .hero-gradient { background: linear-gradient(180deg, rgba(26,47,35,0.1) 0%, rgba(26,47,35,0.8) 100%); }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #b38b59; border-radius: 10px; }
        .nav-blur { backdrop-filter: blur(10px); background: rgba(253, 250, 245, 0.85); }
        .modal-blur { backdrop-filter: blur(12px); background: rgba(26, 47, 35, 0.85); }
      `}</style>
    </div>
  );
};

